CREATE TABLE IF NOT EXISTS cities (id SERIAL PRIMARY KEY,name TEXT NOT NULL,ibge_code TEXT UNIQUE,description TEXT,lat DOUBLE PRECISION,lng DOUBLE PRECISION,zoom INT DEFAULT 13,color TEXT);
CREATE TABLE IF NOT EXISTS places (id SERIAL PRIMARY KEY,city_id INT NOT NULL REFERENCES cities(id),name TEXT NOT NULL,kind TEXT NOT NULL,lat DOUBLE PRECISION NOT NULL,lng DOUBLE PRECISION NOT NULL,description TEXT);
CREATE TABLE IF NOT EXISTS memories (id SERIAL PRIMARY KEY,title TEXT NOT NULL,story TEXT NOT NULL,city_id INT NOT NULL REFERENCES cities(id),neighborhood TEXT,category TEXT,period TEXT,contributor TEXT,lat DOUBLE PRECISION NOT NULL,lng DOUBLE PRECISION NOT NULL,image TEXT,media JSONB DEFAULT '[]',status TEXT NOT NULL DEFAULT 'Aprovado',featured BOOLEAN DEFAULT FALSE,created_at TIMESTAMPTZ DEFAULT NOW());
CREATE TABLE IF NOT EXISTS contributions (id BIGSERIAL PRIMARY KEY,title TEXT NOT NULL,story TEXT NOT NULL,city_id INT NOT NULL REFERENCES cities(id),neighborhood TEXT,category TEXT,period TEXT,contributor TEXT,email TEXT,lat DOUBLE PRECISION,lng DOUBLE PRECISION,authorization BOOLEAN NOT NULL,files JSONB DEFAULT '[]',status TEXT NOT NULL DEFAULT 'Pendente',created_at TIMESTAMPTZ DEFAULT NOW(),updated_at TIMESTAMPTZ DEFAULT NOW());
CREATE TABLE IF NOT EXISTS interviews (id SERIAL PRIMARY KEY,city_id INT REFERENCES cities(id),person_name TEXT,content TEXT,created_at TIMESTAMPTZ DEFAULT NOW());
CREATE TABLE IF NOT EXISTS moderation_events (id BIGSERIAL PRIMARY KEY,contribution_id BIGINT REFERENCES contributions(id),status TEXT,notes TEXT,created_at TIMESTAMPTZ DEFAULT NOW());
CREATE INDEX IF NOT EXISTS idx_memories_city ON memories(city_id);CREATE INDEX IF NOT EXISTS idx_memories_category ON memories(category);CREATE INDEX IF NOT EXISTS idx_contributions_status ON contributions(status);
